    #[cfg(unix)]
    #[test]
    fn ensure_ready_activation_starts_and_cleans_up_native_producer() {
        let _guard = env_mutex_lock();
        let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
        let port = listener
            .local_addr()
            .expect("listener address should resolve")
            .port();
        drop(listener);

        let fixture = ContractFixture::new(
            format!(
                r#"
version: 1
project:
  name: ota
tasks:
  dev:
    run: python3 -c "import socket,time; sock=socket.socket(); sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1); sock.bind(('127.0.0.1', {port})); sock.listen(1); time.sleep(300)"
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: {port}
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: {port}
              path: /
  sandbox:
    run: echo sandbox
    targets:
      api:
        service:
          task: dev
          listener: http
          address_view: host
        activation:
          mode: ensure_ready
"#
            )
            .as_str(),
        );

        let task = fixture
            .contract
            .tasks
            .get("sandbox")
            .expect("sandbox task should exist");
        let target_spec = task
            .targets
            .get("api")
            .expect("target binding should be declared");
        let mut state = TaskRunState::default();
        let status = super::ensure_target_producer_ready(
            &fixture.contract,
            fixture.file_path(),
            "sandbox",
            "api",
            target_spec,
            Backend::Native,
            None,
            TaskExecutionMode::Stream {
                emit_progress: false,
                capture_output: true,
                live_log: None,
            },
            fixture.dir.path(),
            std::env::consts::OS,
            0,
            &mut state,
        )
        .expect("native ensure_ready activation should succeed");

        assert_eq!(status, TaskTargetActivationStatus::StartedReady);

        let cleanup_note = super::cleanup_interrupted_activation_started_producers_and_note(
            &fixture.contract,
            fixture.file_path(),
            fixture.dir.path(),
            &mut state,
        );
        assert!(
            cleanup_note
                .as_deref()
                .is_some_and(|note| note.contains("native service workload cleaned up")),
            "{cleanup_note:?}"
        );

        for _ in 0..30 {
            if !super::target_probe_endpoint_reachable("127.0.0.1", port) {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(100));
        }
        panic!("native activation cleanup should free the producer port");
    }

