    #[test]
    fn ensure_ready_activation_http_readiness_requires_more_than_an_open_port() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
        let port = listener
            .local_addr()
            .expect("listener address should resolve")
            .port();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener
                .accept()
                .expect("http readiness probe should connect");
            let mut buffer = [0u8; 256];
            let _ = stream.read(&mut buffer);
            stream
                .write_all(b"HTTP/1.1 503 Service Unavailable\r\nContent-Length: 2\r\nConnection: close\r\n\r\nno")
                .expect("http readiness probe should write response");
        });
        let fixture = ContractFixture::new(
            format!(
                r#"
version: 1
project:
  name: ota
tasks:
  dev:
    run: echo dev
    runtime:
      kind: service
      readiness:
        kind: http
        listener: http
        path: /health
      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: {port}
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: {port}
  sandbox:
    targets:
      api:
        service:
          task: dev
          listener: http
          address_view: host
        activation:
          mode: ensure_ready
    script: |
      printf '%s' "$OTA_TARGET_API" > target.txt
"#
            )
            .as_str(),
        );

        let error = run_task_captured_with_args_with_overrides(
            &fixture.contract,
            fixture.file_path(),
            "sandbox",
            &[],
            ExecutionOverrides::default(),
        )
        .unwrap_err();

        server
            .join()
            .expect("http readiness probe server should finish");
        assert!(matches!(error, RunError::TaskTargetResolutionFailed { .. }));
        assert!(error.to_string().contains("before becoming ready"));
    }

