    #[test]
    fn ensure_running_activation_reuses_reachable_cross_member_internal_shared_backend_listener() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
        let port = listener
            .local_addr()
            .expect("listener address should resolve")
            .port();
        let server = thread::spawn(move || {
            let _accepted = listener
                .accept()
                .expect("cross-member ensure_running probe should connect");
        });
        let fixture = ContractFixture::new(
            format!(
                r#"
version: 1
project:
  name: ota-monorepo
workspace:
  type: monorepo
  members:
    - api
    - web
execution:
  preferred: native
  shared_backends:
    workbench:
      scope: local
      backend: native
      lifecycle: persistent
tasks:
  root:
    run: echo root
"#
            )
            .as_str(),
        );
        fixture.write(
            "api/ota.yaml",
            format!(
                r#"
tasks:
  dev:
    run: echo api
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: {port}
"#
            )
            .as_str(),
        );
        fixture.write(
            "web/ota.yaml",
            r#"
tasks:
  sandbox:
    run: echo web
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        web:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: 3000
    targets:
      api:
        service:
          member: api
          task: dev
          listener: http
          address_view: internal
        activation:
          mode: ensure_running
"#,
        );

        let (contract, contract_path) =
            load_contract_for_member(fixture.file_path(), "web").unwrap();
        let task = contract
            .tasks
            .get("sandbox")
            .expect("sandbox task should exist");
        let target_spec = task
            .targets
            .get("api")
            .expect("target binding should be declared");
        let status = super::ensure_target_producer_ready(
            &contract,
            &contract_path,
            "sandbox",
            "api",
            target_spec,
            Backend::Native,
            None,
            TaskExecutionMode::Capture,
            fixture.dir.path(),
            std::env::consts::OS,
            0,
            &mut TaskRunState::default(),
        )
        .expect("cross-member ensure_running should accept a reachable shared-backend listener");

        server
            .join()
            .expect("cross-member ensure_running probe server should finish");
        assert_eq!(status, TaskTargetActivationStatus::ReusedRunning);
    }

