    #[test]
    fn task_target_binding_does_not_resolve_listener_from_other_backend_mode() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
tasks:
  dev:
    execution:
      default_mode: native
      modes:
        native:
          run: echo native
          runtime:
            kind: service
            listeners:
              native_http:
                protocol: http
                bind:
                  address: 127.0.0.1
                  port:
                    mode: fixed
                    value: 8081
                project:
                  host:
                    address: 127.0.0.1
                    port:
                      mode: fixed
                      value: 8081
        container:
          run: echo container
          runtime:
            kind: service
            listeners:
              container_http:
                protocol: http
                bind:
                  address: 127.0.0.1
                  port:
                    mode: fixed
                    value: 8080
                project:
                  host:
                    address: 127.0.0.1
                    port:
                      mode: fixed
                      value: 8080
  sandbox:
    inputs:
      base_url:
        required: true
    targets:
      api:
        service:
          task: dev
          listener: container_http
          address_view: topology
        override_input: base_url
    script: |
      printf '%s' "$OTA_INPUT_BASE_URL" > inputs.txt
"#,
        );

        let error = run_task_captured_with_args_with_overrides(
            &fixture.contract,
            fixture.file_path(),
            "sandbox",
            &[],
            ExecutionOverrides::default(),
        )
        .unwrap_err();

        assert!(matches!(error, RunError::TaskTargetResolutionFailed { .. }));
        assert!(
            error
                .to_string()
                .contains("references unknown listener `container_http` on service task `dev`")
        );
    }

