    #[test]
    fn shared_backend_binding_requires_matching_declared_backend_family() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: remote_app
  contexts:
    remote_app:
      backend: remote
      remote:
        provider: ssh
        target: user@host
  shared_backends:
    dev_stack:
      scope: remote
      backend: remote
      lifecycle: persistent
      context: remote_app
tasks:
  dev:
    run: echo dev
    runtime:
      kind: service
      backend_binding: dev_stack
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
  sandbox:
    run: echo sandbox
    runtime:
      kind: service
      backend_binding: dev_stack
      listeners:
        web:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
"#,
        )
        .unwrap();

        assert!(!super::tasks_share_container_local_backend(
            &contract, "sandbox", "dev"
        ));
        assert!(!super::tasks_share_backend_binding(
            &contract,
            "sandbox",
            "dev",
            Backend::Container,
        ));
        assert!(super::tasks_share_backend_binding(
            &contract,
            "sandbox",
            "dev",
            Backend::Remote,
        ));
    }

    #[test]
    fn shared_local_backend_resolution_keeps_publications_task_scoped() {
        if crate::execution::available_container_engines().is_empty() {
            return;
        }
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/dev:latest
  shared_backends:
    workbench:
      scope: local
      backend: container
      lifecycle: persistent
      context: app
tasks:
  dev:
    run: echo dev
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 8080
  sandbox:
    run: echo sandbox
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        web:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 9090
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 9090
"#,
        )
        .unwrap();

        let dev_backend =
            resolve_execution_backend(&contract, "dev", ExecutionOverrides::default()).unwrap();
        let sandbox_backend =
            resolve_execution_backend(&contract, "sandbox", ExecutionOverrides::default()).unwrap();

        let ResolvedExecutionBackend::Container {
            publications: dev_publications,
            ..
        } = dev_backend
        else {
            panic!("dev should resolve to container backend");
        };
        let ResolvedExecutionBackend::Container {
            publications: sandbox_publications,
            ..
        } = sandbox_backend
        else {
            panic!("sandbox should resolve to container backend");
        };

        assert_eq!(dev_publications.len(), 1);
        assert_eq!(dev_publications[0].bind_port, 8080);
        assert_eq!(sandbox_publications.len(), 1);
        assert_eq!(sandbox_publications[0].bind_port, 9090);
    }

    #[test]
    fn shared_local_backend_environment_profile_resolves_policy_image() {
        if crate::execution::available_container_engines().is_empty() {
            return;
        }
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/dev:latest
  shared_backends:
    workbench:
      scope: local
      backend: container
      lifecycle: persistent
      context: app
      environment:
        profile: java-node-workbench
tasks:
  dev:
    run: echo dev
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
"#,
        );
        fixture.write(
            ".ota/org-policy.yaml",
            r#"
policies:
  backend_environment:
    profiles:
      java-node-workbench:
        image: ghcr.io/ota/workbench:2026.04
        source: curated
"#,
        );

        let backend = resolve_execution_backend_with_contract_path(
            &fixture.contract,
            "dev",
            ExecutionOverrides::default(),
            Some(fixture.file_path()),
        )
        .expect("backend should resolve with policy-backed profile");

        let ResolvedExecutionBackend::Container {
            image,
            shared_local_backend: Some(shared),
            ..
        } = backend
        else {
            panic!("expected shared container backend");
        };
        assert_eq!(image, "ghcr.io/ota/workbench:2026.04");
        let environment = shared
            .environment
            .as_ref()
            .expect("shared backend should carry environment evidence");
        assert_eq!(
            environment.effective_profile.as_deref(),
            Some("java-node-workbench")
        );
        assert_eq!(environment.effective_source.as_deref(), Some("curated"));
    }

