    #[test]
    fn run_task_captured_reports_fixed_native_runtime_endpoint() {
        let _guard = env_mutex_lock();
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let port = listener.local_addr().unwrap().port();
        drop(listener);

        let fixture = ContractFixture::new(&format!(
            r#"
version: 1
project:
  name: ota
tasks:
  dev:
    script: |
      python3 - <<'PY'
      import socket
      import time
      sock = socket.socket()
      sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
      sock.bind(("127.0.0.1", {port}))
      sock.listen(1)
      time.sleep(1)
      PY
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: {port}
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: {port}
              path: /
"#
        ));

        let outcome = match run_task_captured(&fixture.contract, fixture.file_path(), "dev") {
            Ok(outcome) => outcome,
            Err(RunError::RuntimeListenerResolutionFailed {
                kind:
                    RuntimeListenerResolutionKind::BindDiscovery(
                        super::RuntimeListenerBindDiscoveryFailure::MultiplePorts { .. },
                    ),
                ..
            }) => return,
            Err(error) => panic!(
                "native runtime discovery should succeed or report multiple ports, got {error:?}"
            ),
        };
        let runtime = outcome
            .runtime
            .expect("fixed native service task should report runtime metadata");
        let listener = runtime
            .listeners
            .get("http")
            .expect("http listener should be present");

        assert_eq!(listener.bind.address, "127.0.0.1");
        assert_eq!(listener.bind.port, port);
        let host = listener
            .resolved
            .as_ref()
            .and_then(|resolved| resolved.host.as_ref())
            .expect("fixed native listener should resolve a host endpoint");
        assert_eq!(host.address, "127.0.0.1");
        assert_eq!(host.port, port);
        let expected_url = format!("http://127.0.0.1:{port}/");
        assert_eq!(host.url.as_deref(), Some(expected_url.as_str()));
    }

    #[test]
    fn run_task_captured_discovers_native_runtime_endpoint() {
        #[cfg(unix)]
        if std::process::Command::new("lsof")
            .arg("-v")
            .output()
            .is_err()
        {
            return;
        }

        let _guard = env_mutex_lock();
        let listener = TcpListener::bind(("127.0.0.1", 0)).expect("probe listener should bind");
        let port = listener
            .local_addr()
            .expect("probe listener address should resolve")
            .port();
        drop(listener);
        let fixture = ContractFixture::new(
            format!(
                r#"
version: 1
project:
  name: ota
tasks:
  dev:
    script: |
      python3 -S <<'PY'
      import socket
      import time
      sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
      sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
      sock.bind(("127.0.0.1", {port}))
      sock.listen(1)
      time.sleep(1)
      PY
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: discover
          project:
            host:
              address: 127.0.0.1
              port:
                mode: auto
              path: /
"#,
            )
            .as_str(),
        );

        let outcome = match run_task_captured(&fixture.contract, fixture.file_path(), "dev") {
            Ok(outcome) => outcome,
            Err(RunError::RuntimeListenerResolutionFailed {
                kind:
                    RuntimeListenerResolutionKind::BindDiscovery(
                        super::RuntimeListenerBindDiscoveryFailure::MultiplePorts { .. },
                    ),
                ..
            }) => return,
            Err(error) => panic!(
                "discovered native runtime endpoint should succeed or report multiple ports, got {error:?}"
            ),
        };
        let runtime = outcome
            .runtime
            .expect("discover native service task should report runtime metadata");
        let listener = runtime
            .listeners
            .get("http")
            .expect("http listener should be present");
        let host = listener
            .resolved
            .as_ref()
            .and_then(|resolved| resolved.host.as_ref())
            .expect("discover native listener should resolve a host endpoint");

        assert!(listener.bind.port > 0);
        assert_eq!(host.address, "127.0.0.1");
        assert_eq!(host.port, listener.bind.port);
        let expected_url = format!("http://127.0.0.1:{}/", listener.bind.port);
        assert_eq!(host.url.as_deref(), Some(expected_url.as_str()));
    }

    #[test]
    fn ready_runtime_public_endpoint_line_uses_resolved_public_url() {
        let runtime = ResolvedTaskRuntime {
            kind: TaskRuntimeKind::Service,
            listeners: BTreeMap::new(),
            primary_listener: Some(String::from("http")),
            primary_endpoint: Some(ResolvedTaskRuntimeEndpoint {
                listener: String::from("http"),
                protocol: TaskRuntimeProtocol::Http,
                bind: ResolvedTaskRuntimeBind {
                    address: String::from("0.0.0.0"),
                    port: 3000,
                },
                host: ResolvedTaskRuntimeHost {
                    address: String::from("127.0.0.1"),
                    port: 49153,
                    url: Some(String::from("http://127.0.0.1:49153/")),
                },
                primary: true,
            }),
            exposed_endpoints: Vec::new(),
        };

        let rendered = strip_test_ansi(
            ready_runtime_public_endpoint_line(&runtime)
                .as_deref()
                .expect("line should render"),
        );
        assert_eq!(
            rendered,
            "\n\n⚈ External:  http://127.0.0.1:49153/\n⦾ Internal:  http://0.0.0.0:3000/\n\n"
        );
    }

    #[test]
    fn readiness_probe_confirms_reachability_during_interrupt_grace_window() {
        let reserved = TcpListener::bind(("127.0.0.1", 0)).expect("reserve a local port");
        let port = reserved
            .local_addr()
            .expect("reserved listener should have a local addr")
            .port();
        drop(reserved);

        let runtime_spec = TaskRuntimeSpec {
            kind: TaskRuntimeKind::Service,
            backend_binding: None,
            readiness: None,
            surfaces: TaskRuntimeSurfaceAttachments::default(),
            normalized_surface_listeners: BTreeSet::new(),
            listeners: BTreeMap::from([(
                String::from("http"),
                TaskRuntimeListenerSpec {
                    protocol: TaskRuntimeProtocol::Http,
                    bind: TaskRuntimeBindSpec {
                        address: String::from("0.0.0.0"),
                        port: TaskRuntimePortSpec {
                            mode: TaskRuntimePortMode::Fixed,
                            value: Some(3000),
                        },
                    },
                    project: TaskRuntimeProjectionSpec {
                        host: Some(TaskRuntimeHostProjectionSpec {
                            address: String::from("127.0.0.1"),
                            port: TaskRuntimeHostPortSpec {
                                mode: TaskRuntimeHostPortMode::Fixed,
                                value: Some(port),
                            },
                            primary: true,
                            path: Some(String::from("/")),
                        }),
                    },
                },
            )]),
        };
        let runtime = ResolvedTaskRuntime {
            kind: TaskRuntimeKind::Service,
            listeners: BTreeMap::new(),
            primary_listener: Some(String::from("http")),
            primary_endpoint: Some(ResolvedTaskRuntimeEndpoint {
                listener: String::from("http"),
                protocol: TaskRuntimeProtocol::Http,
                bind: ResolvedTaskRuntimeBind {
                    address: String::from("0.0.0.0"),
                    port: 3000,
                },
                host: ResolvedTaskRuntimeHost {
                    address: String::from("127.0.0.1"),
                    port,
                    url: Some(format!("http://127.0.0.1:{port}/")),
                },
                primary: true,
            }),
            exposed_endpoints: Vec::new(),
        };

        let interrupt_epoch = super::current_run_interrupt_epoch();
        let probe = super::start_runtime_readiness_probe(
            None,
            Some(&runtime_spec),
            Some(&runtime),
            false,
            None,
            interrupt_epoch,
        )
        .expect("probe should start");

        thread::sleep(std::time::Duration::from_millis(25));
        super::simulate_run_interrupt_for_test();
        thread::sleep(std::time::Duration::from_millis(75));
        let listener = TcpListener::bind(("127.0.0.1", port)).expect("bind listener");
        let observed = {
            let _listener = listener;
            thread::sleep(std::time::Duration::from_millis(120));
            probe.stop_and_collect()
        };

        assert!(observed, "interrupt grace window should confirm readiness");
    }

