    #[test]
    fn remote_http_probe_command_does_not_follow_redirects() {
        let request = HttpReadinessRequest {
            method: TaskRuntimeReadinessHttpMethod::Get,
            path: String::from("/ready"),
            headers: BTreeMap::new(),
            success_statuses: vec![302],
            body_contains: None,
        };

        let command = super::remote_http_readiness_probe_command(
            "http://127.0.0.1:3000/ready",
            &request,
            None,
        );

        assert!(!command.contains("curl -sS -L"));
        assert!(command.contains("class NoRedirect(urllib.request.HTTPRedirectHandler):"));
        assert!(!command.contains("wget -q -O /dev/null"));
    }

    #[test]
    fn remote_http_probe_command_python_path_handles_http_error_statuses() {
        let request = HttpReadinessRequest {
            method: TaskRuntimeReadinessHttpMethod::Get,
            path: String::from("/health"),
            headers: BTreeMap::new(),
            success_statuses: vec![401, 503],
            body_contains: Some(String::from("DOWN")),
        };

        let command = super::remote_http_readiness_probe_command(
            "http://127.0.0.1:8080/health",
            &request,
            Some(Duration::from_secs(3)),
        );

        assert!(command.contains("except urllib.error.HTTPError as error:"));
        assert!(command.contains("status = error.code"));
        assert!(command.contains("body = error.read().decode(errors='ignore')"));
        assert!(command.contains("timeout='3'"));
    }

    fn strip_test_ansi(value: &str) -> String {
        let mut out = String::new();
        let mut chars = value.chars().peekable();
        while let Some(ch) = chars.next() {
            if ch == '\u{1b}' && chars.peek() == Some(&'[') {
                let _ = chars.next();
                for next in chars.by_ref() {
                    if ('@'..='~').contains(&next) {
                        break;
                    }
                }
            } else {
                out.push(ch);
            }
        }
        out
    }

    #[cfg(unix)]
    #[test]
    fn resolves_task_backend_from_bound_execution_context() {
        #[cfg(unix)]
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/test:latest
        engines:
          - podman
      attachments:
        compose:
          - local
services:
  postgres:
    manager:
      kind: compose
      name: local
      service: postgres
tasks:
  compose:up:
    context: host
    run: echo host
  dev:
    context: app
    run: echo dev
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 3000
  build:
    context: app
    run: echo build
"#,
        );

        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let podman_path = bin_dir.join("podman");
        install_fake_container_engine(&podman_path);
        #[cfg(unix)]
        {
            let mut permissions = fs::metadata(&podman_path).unwrap().permissions();
            permissions.set_mode(0o755);
            fs::set_permissions(&podman_path, permissions).unwrap();
        }
        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        assert!(matches!(
            resolve_execution_backend(
                &fixture.contract,
                "compose:up",
                ExecutionOverrides::default()
            )
            .unwrap(),
            ResolvedExecutionBackend::Native { .. }
        ));

        let build_backend =
            resolve_execution_backend(&fixture.contract, "build", ExecutionOverrides::default())
                .unwrap();
        match build_backend {
            ResolvedExecutionBackend::Container {
                image,
                engine,
                lifecycle,
                compose_networks,
                publications,
                ..
            } => {
                assert_eq!(image, "ghcr.io/ota/test:latest");
                assert_eq!(engine, "podman");
                assert_eq!(lifecycle, Lifecycle::Persistent);
                assert_eq!(compose_networks, vec![String::from("local_default")]);
                assert!(publications.is_empty());
            }
            other => panic!("expected container backend, got {other:?}"),
        }

        let dev_backend =
            resolve_execution_backend(&fixture.contract, "dev", ExecutionOverrides::default())
                .unwrap();
        match dev_backend {
            ResolvedExecutionBackend::Container { publications, .. } => {
                assert_eq!(publications.len(), 1);
                assert_eq!(publications[0].bind_port, 3000);
                assert_eq!(publications[0].host_address, "127.0.0.1");
            }
            other => panic!("expected container backend, got {other:?}"),
        }

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }
    }

    #[test]
    fn execute_task_with_hooks_caches_final_exit_after_hook_failures() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
tasks:
  build:
    run: echo build
    after_success: [verify]
  verify:
    run: exit 42
"#,
        );

        let backend =
            resolve_execution_backend(&fixture.contract, "build", ExecutionOverrides::default())
                .unwrap();
        let mut state = TaskRunState::default();
        let working_dir = contract_working_dir(fixture.file_path());
        let current_os = current_os();

        let first_exit = execute_task_with_hooks(
            &fixture.contract,
            fixture.file_path(),
            "build",
            &[],
            ExecutionOverrides::default(),
            None,
            &backend,
            TaskExecutionMode::Capture,
            working_dir,
            current_os,
            TaskExecutionRelation::Requested,
            0,
            &mut state,
        )
        .unwrap();
        assert_eq!(first_exit, 42);
        assert_eq!(state.completed.get("build"), Some(&42));

        let step_count = state.task_steps.len();
        let second_exit = execute_task_with_hooks(
            &fixture.contract,
            fixture.file_path(),
            "build",
            &[],
            ExecutionOverrides::default(),
            None,
            &backend,
            TaskExecutionMode::Capture,
            working_dir,
            current_os,
            TaskExecutionRelation::Requested,
            0,
            &mut state,
        )
        .unwrap();
        assert_eq!(second_exit, 42);
        assert_eq!(state.task_steps.len(), step_count);
    }

    #[test]
    fn reruns_after_success_tasks_even_if_completed_as_dependencies() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota-site
tasks:
  setup:
    script: |
      echo setup >> run.log
  build:
    depends_on:
      - setup
    after_success:
      - discoverability:check
    script: |
      echo build >> run.log
  typecheck:
    depends_on:
      - setup
    script: |
      echo typecheck >> run.log
  deadcode:
    depends_on:
      - setup
    script: |
      echo deadcode >> run.log
  discoverability:check:
    depends_on:
      - setup
    script: |
      echo discoverability >> run.log
  ci:
    depends_on:
      - build
      - typecheck
      - deadcode
      - discoverability:check
    script: |
      echo ci >> run.log
  version:bump:
    inputs:
      version:
        default: patch
    run: echo version-bump >> run.log
    depends_on: [ ci, deadcode ]
    after_success:
      - build
"#,
        );

        let outcome = run_task_with_args(
            &fixture.contract,
            fixture.file_path(),
            "version:bump",
            &[String::from("--version"), String::from("patch")],
        )
        .unwrap();

        assert_eq!(outcome.exit_code, 0);
        assert_eq!(
            fs::read_to_string(fixture.dir.path().join("run.log"))
                .unwrap()
                .lines()
                .collect::<Vec<_>>(),
            vec![
                "setup",
                "build",
                "discoverability",
                "typecheck",
                "deadcode",
                "ci",
                "version-bump",
                "setup",
                "build",
                "discoverability",
            ]
        );
        assert_eq!(
            outcome.executed_tasks,
            vec![
                String::from("setup"),
                String::from("build"),
                String::from("discoverability:check"),
                String::from("typecheck"),
                String::from("deadcode"),
                String::from("ci"),
                String::from("version:bump"),
                String::from("setup"),
                String::from("build"),
                String::from("discoverability:check"),
            ]
        );
    }

